import{_ as s,o as n,c as e,a6 as i}from"./chunks/framework.DL_pga9_.js";const d=JSON.parse('{"title":"Generics","description":"","frontmatter":{},"headers":[],"relativePath":"guide/generics.md","filePath":"guide/generics.md","lastUpdated":1781686130000}'),t={name:"guide/generics.md"};function p(l,a,r,c,o,h){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="generics" tabindex="-1">Generics <a class="header-anchor" href="#generics" aria-label="Permalink to “Generics”">​</a></h1><p>Generics allow you to write code that works with multiple types while preserving static type safety.</p><h2 id="generic-functions" tabindex="-1">Generic Functions <a class="header-anchor" href="#generic-functions" aria-label="Permalink to “Generic Functions”">​</a></h2><h3 id="basic-type-parameters" tabindex="-1">Basic Type Parameters <a class="header-anchor" href="#basic-type-parameters" aria-label="Permalink to “Basic Type Parameters”">​</a></h3><p>Place type parameters in angle brackets after the function name:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun identity&lt;T&gt;(x: T) -&gt; T {</span></span>
<span class="line"><span>    return x;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>identity(42);        // T is inferred as i32</span></span>
<span class="line"><span>identity(&quot;hello&quot;);   // T is inferred as string</span></span>
<span class="line"><span>identity(true);      // T is inferred as bool</span></span></code></pre></div><p>Type parameters are <strong>inferred</strong> from the arguments — you rarely need to specify them explicitly.</p><h3 id="multiple-type-parameters" tabindex="-1">Multiple Type Parameters <a class="header-anchor" href="#multiple-type-parameters" aria-label="Permalink to “Multiple Type Parameters”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun pair&lt;A, B&gt;(a: A, b: B) -&gt; (A, B) {</span></span>
<span class="line"><span>    return (a, b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val p = pair(1, &quot;world&quot;);   // (i32, string)</span></span></code></pre></div><h3 id="type-constraints" tabindex="-1">Type Constraints <a class="header-anchor" href="#type-constraints" aria-label="Permalink to “Type Constraints”">​</a></h3><p>You can constrain type parameters with a fixed set of allowed types:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun add&lt;T: i32 | f64&gt;(a: T, b: T) -&gt; T {</span></span>
<span class="line"><span>    return a + b;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>add(1, 2);          // OK: i32</span></span>
<span class="line"><span>add(1.5, 2.5);      // OK: f64</span></span>
<span class="line"><span>// add(&quot;a&quot;, &quot;b&quot;);</span><span>   // ERROR: string not in constraint</span></span></code></pre></div><h2 id="parameter-packs" tabindex="-1">Parameter Packs <a class="header-anchor" href="#parameter-packs" aria-label="Permalink to “Parameter Packs”">​</a></h2><p>Parameter packs allow variable-arity generic functions. A pack parameter uses <code>...</code> suffix and receives a tuple:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun count&lt;T...&gt;(args: T...) -&gt; u32 {</span></span>
<span class="line"><span>    return args.size;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>count(1, &quot;two&quot;, 3.0, true);   // returns 4</span></span></code></pre></div><h3 id="destructuring-packs" tabindex="-1">Destructuring Packs <a class="header-anchor" href="#destructuring-packs" aria-label="Permalink to “Destructuring Packs”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun printEach&lt;T...&gt;(args: T...) {</span></span>
<span class="line"><span>    if (args.size &gt; 0) {</span></span>
<span class="line"><span>        val (head, ...tail) = args;</span></span>
<span class="line"><span>        print(head);</span></span>
<span class="line"><span>        next ...tail;    // recurse with remaining elements</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>printEach(1, &quot;hello&quot;, true);</span></span></code></pre></div><h3 id="constraints-on-packs" tabindex="-1">Constraints on Packs <a class="header-anchor" href="#constraints-on-packs" aria-label="Permalink to “Constraints on Packs”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun sum&lt;T: i32 | f64...&gt;(args: T...) -&gt; T {</span></span>
<span class="line"><span>    // Only works for numeric types</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="generic-types" tabindex="-1">Generic Types <a class="header-anchor" href="#generic-types" aria-label="Permalink to “Generic Types”">​</a></h2><h3 id="generic-object-types" tabindex="-1">Generic Object Types <a class="header-anchor" href="#generic-object-types" aria-label="Permalink to “Generic Object Types”">​</a></h3><p>Types can be parameterized too:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Box&lt;T&gt; {</span></span>
<span class="line"><span>    value: T;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val intBox = new Box&lt;i32&gt; { value: 42 };</span></span>
<span class="line"><span>val strBox = new Box&lt;string&gt; { value: &quot;hello&quot; };</span></span></code></pre></div><h3 id="generic-tagged-unions" tabindex="-1">Generic Tagged Unions <a class="header-anchor" href="#generic-tagged-unions" aria-label="Permalink to “Generic Tagged Unions”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Option&lt;T&gt; = Some(value: T) | None;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun unwrapOr&lt;T&gt;(opt: Option&lt;T&gt;, fallback: T) -&gt; T {</span></span>
<span class="line"><span>    switch (opt) {</span></span>
<span class="line"><span>        case Some(v) { return v; }</span></span>
<span class="line"><span>        case None { return fallback; }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="generic-type-aliases" tabindex="-1">Generic Type Aliases <a class="header-anchor" href="#generic-type-aliases" aria-label="Permalink to “Generic Type Aliases”">​</a></h3><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Pair&lt;T&gt; = (T, T);</span></span>
<span class="line"><span>type Result&lt;T, E&gt; = Ok(value: T) | Err(error: E);</span></span></code></pre></div><h2 id="generic-newtypes" tabindex="-1">Generic Newtypes <a class="header-anchor" href="#generic-newtypes" aria-label="Permalink to “Generic Newtypes”">​</a></h2><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>newtype Wrapper&lt;T&gt; = T;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val w = Wrapper&lt;i32&gt;(42);</span></span></code></pre></div><h2 id="generic-instance-mangling" tabindex="-1">Generic Instance Mangling <a class="header-anchor" href="#generic-instance-mangling" aria-label="Permalink to “Generic Instance Mangling”">​</a></h2><p>Each generic instantiation gets a unique <strong>mangled name</strong> that encodes the module path and concrete type arguments. This ensures type safety across module boundaries:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// Module A</span></span>
<span class="line"><span>export fun foo&lt;T&gt;(x: T) -&gt; T =&gt; x;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Module B</span></span>
<span class="line"><span>import A;</span></span>
<span class="line"><span>val x = foo(42);    // calls A::foo&lt;i32&gt;</span></span>
<span class="line"><span>val y = foo(&quot;hi&quot;);  // calls A::foo&lt;string&gt; — different instance</span></span></code></pre></div><h2 id="const-generic-parameters" tabindex="-1">Const Generic Parameters <a class="header-anchor" href="#const-generic-parameters" aria-label="Permalink to “Const Generic Parameters”">​</a></h2><p>Type parameters can be constrained by compile-time constant values:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun fixedArray&lt;T, const N: i32&gt;() -&gt; [T; N] {</span></span>
<span class="line"><span>    // Returns an array of type [T; N]</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val arr: [i32; 5] = fixedArray&lt;i32, 5&gt;();</span></span></code></pre></div><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to “What&#39;s Next?”">​</a></h2><p>Continue to <a href="./references-moves">References, Moves &amp; Ownership</a> to learn about NG&#39;s ownership model.</p><blockquote><p><strong>Try it:</strong> <code>example/15.generics.ng</code> — Basic generics <strong>Try it:</strong> <code>example/52.const_array_vector_span.ng</code> — Const generic parameters</p></blockquote>`,38)])])}const u=s(t,[["render",p]]);export{d as __pageData,u as default};
